pragma solidity >=0.4.24 <0.8.0; library SafeMath {
function add(uint256 a,uint256 b) internal pure returns(uint256 c){c=a+b;require(c>=a);}
function sub(uint256 a,uint256 b) internal pure returns(uint256){require(b<=a);return a-b;}
function mul(uint256 a,uint256 b) internal pure returns(uint256 c){if(a==0)return 0;c=a*b;require(c/a==b);}
function div(uint256 a,uint256 b) internal pure returns(uint256){require(b>0);return a/b;}
function mod(uint256 a,uint256 b) internal pure returns(uint256){require(b>0);return a%b;}}

